library(dplyr)
library(stringr)
library(tidyr)

# ======================================================================================
# 03 - FUNCTIONAL IMPACT OF DIFFERENTIALLY SPLICED EXONS AND INTRONS
# ======================================================================================
# Input:
#   - dPSI tables generated by 01_Filtering_AS_events.R
#   - VAST-TOOLS/VastDB protein impact annotations (downloaded from VastDB)
#
# Analysis:
#   - Correct formatting issues in the VAST-TOOLS protein impact annotation file
#   - Identify differentially spliced events using abs(dPSI) > 10
#   - Classify splicing changes as exon/intron inclusion or exclusion
#   - Associate differential splicing events with predicted functional impacts
#   - Simplify impact annotations into protein isoforms, ORF disruption,
#     UTR/NonCoding and uncertain impact categories
#   - Export impact classifications with separate and combined UTR categories

#
# Output:
#   - Differentially spliced events with raw protein impact annotations (Excel and RData)
#   - Filtered events with simplified functional impact categories (Excel and RData)
#
# Dependencies:
#   - 01_Filtering_AS_events.R (input data)
#   - 00_utils.R
#   - dplyr, stringr, tidyr and additional R packages managed through renv
#
# ======================================================================================

# paths
root_dir <- "C:/Users/msalinas/OneDrive - CRG - Centre de Regulacio Genomica/Desktop/DATA/Acral_melanoma/AM202607/"
files_dir <- file.path(root_dir,"code_paper","downstream_analyses" ,"AS", "Files")
graphs_dir <- file.path(root_dir,"code_paper","downstream_analyses" ,"AS", "Graphs")

if (!dir.exists(files_dir)) {dir.create(files_dir, recursive = TRUE)}
if (!dir.exists(graphs_dir)) {dir.create(graphs_dir, recursive = TRUE)}

# dPSI_values 
dPSI_annot <- read.table(file.path(files_dir,"IncTable_dPSI_values_AMcelllines_sgSF3B4_n356613.txt"), sep="\t", header=TRUE)

# params
dPSI_threshold <- 10 # dPSI threshold to consider diff spliced events
conditions <- colnames(dPSI_annot)[7:ncol(dPSI_annot)] # name of conditions to consider

# prot_impact file from VastDB (hg38_v2.3)
prot_impact <- read.table("C:/Users/msalinas/OneDrive - CRG - Centre de Regulacio Genomica/Desktop/AnnotationFiles/Vast-tools/PROT_IMPACT-hg38-v2.3.tab", 
                          sep="\t", header=TRUE)

# functions/utils
source(file.path(root_dir,"code_paper/downstream_analyses/00_utils.R"))

# ===================================================================
# Fixing prot_impact format before running analyses
colnames(prot_impact) <- c("EVENT", "impact")


# check how many rows contain some EVENT ID in the impact column 
prot_impact %>%
  filter(grepl("Hsa", impact, ignore.case = TRUE)) %>%
  nrow()  # 32423



# keep the rows that are ok
prot_impact_ok <- prot_impact %>%
  filter(!grepl("Hsa", impact, ignore.case = TRUE))


# keep impact column to fix it
to_fix <- prot_impact

# keep the rows that are ok
to_fix <- to_fix %>%
  filter(grepl("Hsa", impact, ignore.case = TRUE))


# Separar la columna 'impact' en dos columnas: 'impact' y 'to_fix'
to_fix_1 <- to_fix %>%
  mutate(
    impact = sub("(Hsa.*)", "", impact),                # Extraer la parte antes del primer 'Hsa'
    to_fix = sub(".*?(Hsa.*)", "\\1", impact)           # Extraer el resto a partir del primer 'Hsa'
  ) %>% select(EVENT, impact)




# use mutate y strsplit to divide the column in multiple files, one per each EVENT ID found
to_fix_2 <- to_fix %>%
  # Useparate_rows to divide col using Hsa pattern 
  mutate(impact = gsub("(?<=\\w)(?=Hsa)", "\n", impact, perl = TRUE)) %>%
  separate_rows(impact, sep = "\n") %>%
  # remove empty rows
  filter(impact != "")

# if a row is not starting by Hsa, it was the impact description of the EVENT in col1 (already in prot_impact_ok) 
to_fix_2 <- to_fix_2 %>%
  filter(grepl("^Hsa", impact))



# separate into EVENT and impact columns 
to_fix_2 <- to_fix_2 %>%
  mutate(
    # EVENT is the first word starting by Hsa and up to the first space (the whole event ID) 
    EVENT = str_extract(impact, "Hsa\\S+"),
    # impact is the rest
    impact = str_trim(sub("Hsa\\S+", "", impact))
  ) %>%
  select(EVENT, impact)


# bind all, the ones that were originally well formatted and the fixed ones
all <- rbind (prot_impact_ok, to_fix_1, to_fix_2)
colnames(all) <- c("EVENT", "IMPACT")  #721644
prot_impact <- all


