                                      dpsi_threshold     = dPSI_threshold,
                                      col_splicing       = "Splicing_change",
                                      col_event_type     = "EVENT_TYPE",
                                      col_impact         = "IMPACT",
                                      env_all_name       = "diff_events",
                                      env_filtered_name  = "diff_events_filtered",
                                      separate_UTR       = "yes", 
                                      output_dir         = files_dir,
                                      file_base_name     = "Functional_impact_diff_exons_introns_UTR_NonCoding")


filter_and_export_impact_diff_events (dpsi_df            = dPSI_annot,
                                      conditions         = conditions,
                                      impact_df          = prot_impact,
                                      dpsi_threshold     = dPSI_threshold,
                                      col_splicing       = "Splicing_change",
                                      col_event_type     = "EVENT_TYPE",
                                      col_impact         = "IMPACT",
                                      env_all_name       = "diff_events",
                                      env_filtered_name  = "diff_events_filtered",
                                      separate_UTR       = "no", 
                                      output_dir         = files_dir,
                                      file_base_name     = "Functional_impact_diff_exons_introns")



